insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cosa si fa nella prima visita?', $quth1ly$["come funziona la prima visita","cosa succede alla prima visita","che cosa comprende la prima visita","cosa si fa alla prima visita"]$quth1ly$::jsonb, 'In genere la prima visita comprende alcune domande sulla sua salute e sulle sue abitudini, un controllo di denti e gengive e, se il dentista lo ritiene utile, delle radiografie. Alla fine il dentista le illustra il percorso di cura consigliato.', $qqpdt9j${}$qqpdt9j$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Quanto dura una seduta di igiene dentale?', $qyky5w4$["quanto dura l igiene","quanto dura la pulizia dei denti","quanto tempo ci vuole per l igiene","quanto dura la pulizia"]$qyky5w4$::jsonb, 'Una seduta di igiene dentale dura in genere tra i 30 e i 60 minuti; il tempo esatto dipende dalla situazione di ciascuno.', $q8ru1r9${}$q8ru1r9$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa l''igiene dentale?', $qyjs348$["ogni quanto si fa la pulizia dei denti","ogni quanto devo fare l igiene","quante volte l anno si fa l igiene","ogni quanto va fatta la pulizia"]$qyjs348$::jsonb, 'Di solito si consiglia l''igiene professionale una o due volte l''anno, ma è il dentista a indicare la frequenza più adatta a ciascuna persona.', $qleae7v${}$qleae7v$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Ogni quanto è bene fare un controllo dal dentista?', $qnt8vtd$["ogni quanto devo fare il controllo dal dentista","ogni quanto va fatta la visita di controllo","ogni quanto si va dal dentista","ogni quanto controllo"]$qnt8vtd$::jsonb, 'In genere è consigliato un controllo ogni sei mesi o una volta l''anno; il dentista può indicare una frequenza diversa in base alle esigenze.', $qtpj5cb${}$qtpj5cb$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Lo sbiancamento fa male?', $qtu39d4$["lo sbiancamento e doloroso","fa male sbiancare i denti","lo sbiancamento da fastidio","lo sbiancamento rovina i denti"]$qtu39d4$::jsonb, 'Lo sbiancamento può causare una sensibilità temporanea dei denti. Il dentista valuta in visita se è adatto al suo caso e come eseguirlo.', $qi2cnjj${}$qi2cnjj$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Come funziona lo sbiancamento dentale?', $qh1b3bp$["come si fa lo sbiancamento","come funziona lo sbiancamento","in cosa consiste lo sbiancamento","quanto dura lo sbiancamento"]$qh1b3bp$::jsonb, 'Lo sbiancamento schiarisce il colore dei denti con prodotti specifici applicati dal dentista o usati a casa sotto il suo controllo. Il risultato e i tempi dipendono dal singolo caso, per questo serve una visita di valutazione.', $q5j1fwz${}$q5j1fwz$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Quanto dura l''effetto dello sbiancamento?', $q6k1api$["quanto dura lo sbiancamento nel tempo","per quanto tempo restano bianchi i denti","l effetto dello sbiancamento e permanente"]$q6k1api$::jsonb, 'La durata dell''effetto dipende dal caso e dalle abitudini (per esempio fumo, caffè, tè); il dentista può indicare cosa aspettarsi.', $qabxewp${}$qabxewp$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è la devitalizzazione?', $qyile1s$["cosa e la devitalizzazione","in cosa consiste la devitalizzazione","cosa significa devitalizzare un dente","cos e la cura canalare","come funziona la devitalizzazione"]$qyile1s$::jsonb, 'La devitalizzazione, o terapia canalare, tratta l''interno del dente (il nervo e i canali) quando è infiammato o infetto, per poter conservare il dente. Serve una visita per capire se è necessaria.', $qr40dcx${}$qr40dcx$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è un impianto dentale?', $qwzctke$["cosa e un impianto dentale","come funziona un impianto","in cosa consiste l impianto","come si fa un impianto","cos e l implantologia"]$qwzctke$::jsonb, 'L''impianto è una radice artificiale, in genere di titanio, inserita nell''osso: su di essa si fissa il nuovo dente. Tempi e modalità vengono definiti dal dentista dopo la visita.', $qxhnr3m${}$qxhnr3m$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'L''impianto dentale fa male?', $q0h16wj$["fa male l impianto","l impianto e doloroso","si sente dolore con l impianto","si sente male durante l impianto"]$q0h16wj$::jsonb, 'L''intervento viene eseguito con anestesia locale. Per decorso e indicazioni successive il dentista dà istruzioni specifiche per il suo caso.', $qnmboln${}$qnmboln$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è una corona o capsula dentale?', $qvqfrzk$["cosa e una corona dentale","cosa e una capsula","a cosa serve la corona","cos e la capsula","cos e una corona"]$qvqfrzk$::jsonb, 'La corona (o capsula) è un rivestimento che ricopre un dente danneggiato per proteggerlo e ripristinarne forma e funzione.', $qdaxkhl${}$qdaxkhl$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Si usa l''anestesia?', $qt13gj9$["serve l anestesia","fanno l anestesia","si sente male con l anestesia","mi fate l anestesia","si usa l anestesia"]$qt13gj9$::jsonb, 'Quando una cura può dare fastidio il dentista utilizza l''anestesia locale e ne parla prima con il paziente.', $q3kz18b${}$q3kz18b$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Ho paura del dentista, cosa posso fare?', $qu04jni$["ho paura del dentista","ho il terrore del dentista","sono molto ansioso per il dentista","ho l ansia del dentista","mi spaventa il dentista"]$qu04jni$::jsonb, 'È molto comune: chi lavora in uno studio dentistico è abituato ad accogliere chi ha timore. Può dirlo al momento dell''appuntamento, così il dentista procede con i tempi giusti per lei.', $qbtwi9u${}$qbtwi9u$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Da che età si porta un bambino dal dentista?', $qqj3l57$["da che eta si porta il bambino dal dentista","quando portare mio figlio dal dentista","a che eta la prima visita del bambino","da quando si va dal dentista da piccoli"]$qqj3l57$::jsonb, 'In generale si consiglia una prima visita intorno ai 3-4 anni, o prima se ci sono dubbi o disturbi. Per i dettagli sui bambini è meglio confrontarsi con lo studio.', $qqn9rgl${}$qqn9rgl$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_documenti', 'Cosa devo portare alla prima visita?', $qrymnko$["cosa devo portare alla visita","che documenti servono per la prima visita","cosa serve portare","devo portare qualcosa alla prima visita"]$qrymnko$::jsonb, 'Alla prima visita è utile portare un documento di identità, la tessera sanitaria, eventuali radiografie o referti precedenti e l''elenco dei farmaci che assume. Per altre indicazioni verifichi con lo studio.', $q7d9tth${}$q7d9tth$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Servono le radiografie?', $qh5std2$["devo fare le radiografie","fate le radiografie","serve la radiografia","ci vuole la radiografia"]$qh5std2$::jsonb, 'La radiografia viene eseguita solo se il dentista la ritiene necessaria per la valutazione.', $qk5kic4${}$qk5kic4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'I denti del giudizio vanno sempre tolti?', $qvvi3ct$["vanno tolti i denti del giudizio","devo togliere il dente del giudizio","i denti del giudizio vanno estratti"]$qvvi3ct$::jsonb, 'Non sempre: è il dentista a valutare se estrarli, di solito con una radiografia e una visita.', $qoy1kgu${}$qoy1kgu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Quanto dura un trattamento ortodontico?', $qf2i1fm$["quanto dura l apparecchio","quanto tempo si porta l apparecchio","quanto dura la cura ortodontica","per quanto tempo si porta l apparecchio"]$qf2i1fm$::jsonb, 'La durata varia molto da caso a caso, spesso da alcuni mesi a un paio d''anni. Il piano viene definito dal dentista dopo la visita.', $q198wi5${}$q198wi5$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cosa sono gli allineatori trasparenti?', $qha3351$["cosa sono gli aligner","cos e invisalign","come funzionano le mascherine trasparenti","cosa sono gli allineatori","l apparecchio trasparente funziona"]$qha3351$::jsonb, 'Gli allineatori trasparenti sono mascherine rimovibili che spostano gradualmente i denti: in alcuni casi sono un''alternativa all''apparecchio fisso. La valutazione spetta al dentista.', $qkghcba${}$qkghcba$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Posso andare dal dentista in gravidanza?', $qq902ss$["si puo andare dal dentista in gravidanza","sono incinta posso fare l igiene","sono in gravidanza posso curarmi i denti","dentista in gravidanza"]$qq902ss$::jsonb, 'In gravidanza è importante avvisare lo studio: il dentista valuta quali cure sono adatte e in quale momento.', $qniox56${}$qniox56$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cosa causa l''alito cattivo?', $q3cl2vd$["perche ho l alito cattivo","cosa fare per l alitosi","da cosa dipende l alitosi","come si cura l alitosi"]$q3cl2vd$::jsonb, 'L''alito pesante può avere cause diverse: serve una visita per capire da dove dipende, e il dentista indica come intervenire.', $qonxnqs${}$qonxnqs$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è l''otturazione?', $qxx8erp$["cosa e l otturazione","come si fa un otturazione","in cosa consiste l otturazione","come funziona l otturazione"]$qxx8erp$::jsonb, 'L''otturazione serve a ricostruire la parte di dente rovinata, per esempio da una carie, dopo averla pulita. Il dentista stabilisce in visita il tipo di intervento.', $q5av9p0${}$q5av9p0$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Dopo un''estrazione o un intervento cosa devo fare?', $q2n1c2n$["cosa devo fare dopo l estrazione","cosa fare dopo l intervento","dopo l estrazione cosa si fa","indicazioni dopo un intervento dentale"]$q2n1c2n$::jsonb, 'Dopo un intervento il dentista dà indicazioni specifiche per il suo caso: le segua con attenzione. Per sintomi particolari contatti direttamente lo studio.', $qin6dma${}$qin6dma$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('dentista', 1, 'production', 'info_trattamenti', 'Cos''è l''igiene dentale professionale?', $qe7b0do$["cosa e l igiene dentale","a cosa serve l igiene dentale","cosa si fa nell igiene","in cosa consiste la pulizia dei denti","a cosa serve la pulizia dei denti"]$qe7b0do$::jsonb, 'L''igiene professionale rimuove placca e tartaro che lo spazzolino non elimina e lucida i denti: aiuta a mantenere sane gengive e denti.', $q72p7o0${}$q72p7o0$::jsonb);
insert into sector_eval_runs (profile_id, settore, version, scenari_totali, scenari_passati, metriche, gate_passed, note)
